<script setup>defineProps({carregando:Boolean,erro:{type:String,default:''},vazio:Boolean});defineEmits(['repetir'])</script>
<template><div v-if="carregando" class="data-state" role="status" aria-live="polite"><span class="spinner" aria-hidden="true"/> A consultar dados oficiais…</div><div v-else-if="erro" class="data-state data-error" role="alert"><strong>Não foi possível carregar os indicadores.</strong><p>{{erro}}</p><button class="btn btn-outline" type="button" @click="$emit('repetir')">Tentar novamente</button></div><div v-else-if="vazio" class="data-state">Não existem valores disponíveis para esta série.</div></template>
